260  // Fuzzer inspired by /src/jq_test.c
   261  // The goal is to have the fuzzer execute the functions:
   262  // jq_compile -> jv_parse -> jq_next.
   263  extern "C" int LLVMFuzzerTestOneInput(uint8_t *data, size_t size) {
   264    FuzzedDataProvider fdp(data, size);
   265    std::string parse_payload1 = fdp.ConsumeRandomLengthString();
   266    std::string parse_payload2 = fdp.ConsumeRandomLengthString();
   267
   268    int idx = fdp.ConsumeIntegralInRange<int>(
   269        0, (sizeof(jq_progs) / sizeof(char *)) - 1);
   270
   271    jq_state *jq = NULL;
   272    jq = jq_init();
   273    if (jq != NULL) {
   274      jq_set_attr(jq, jv_string("JQ_ORIGIN"), jv_string("/tmp/"));
   275
   276      if (jq_compile(jq, jq_progs[idx])) {
   277        // Process to jv_parse and then jv_next
   278        jv input = jv_parse(parse_payload1.c_str());
   279        if (jv_is_valid(input)) {
   280          jq_start(jq, input, 0);
   281          jv next = jv_parse(parse_payload2.c_str());
   282          if (jv_is_valid(next)) {
   283            jv actual = jq_next(jq);
   284            jv_free(actual);
   285          }
   286          jv_free(next);
   287        } else {
   288          // Only free if input is invalid as otherwise jq_teardown
   289          // frees it.
   290          jv_free(input);
   291        }
   292      }
   293    }
   294    jq_teardown(&jq);
   295
   296    return 0;
   297  }
